# ============ UNIVERSE ============
import io
import gzip
import base64
import csv
import re
import pandas as pd

# Embedded master dataset of top 1,000 NSE liquid stocks (Self-contained)
EMBEDDED_DATA_B64 = ""

# Extended candidate pool: NSE EQUITY_L snapshot ke wo symbols jo embedded
# top-1000 catalog me nahi hain (symbol + company name, gzip+base64).
# Ye sirf POOL hai - inme se top (UNIVERSE_SIZE - 1000) hi turnover ranking ke
# baad scan hote hain. Runtime par NSE ka live list milta hai to wo use hota hai
# (fresher); ye blob fallback hai taaki NSE block hone par bhi 1500 pahunche.
EXTRA_SYMBOLS_B64 = ""

UNIVERSE_DUPLICATES = []  # diagnostics: skipped duplicate symbols (Phase 1)


def get_universe_df(universe_type="top1000"):
    global UNIVERSE_DUPLICATES
    raw_csv = gzip.decompress(base64.b64decode(EMBEDDED_DATA_B64)).decode('utf-8')
    df = pd.read_csv(io.StringIO(raw_csv))

    if 'symbol' not in df.columns and 'Symbol' in df.columns:
        df['symbol'] = df['Symbol']
    if 'name' not in df.columns and 'Company Name' in df.columns:
        df['name'] = df['Company Name']
    if 'industry' not in df.columns and 'Industry' in df.columns:
        df['industry'] = df['Industry']

    df['Yahoo_Ticker'] = df['symbol'].astype(str) + ".NS"

    # Phase 1 fix: catalog me 2 symbols duplicate the (INOXGREEN, TRIVENI). Same
    # ticker do baar scan hone se report me ek hi stock ki duplicate row aa sakti
    # thi. Pehla occurrence rakho, baaki skip karo (observation only - koi unique
    # ticker nahi hatta).
    _dups = df['symbol'][df['symbol'].duplicated()].astype(str).tolist()
    if _dups:
        UNIVERSE_DUPLICATES = _dups
        df = df.drop_duplicates(subset='symbol', keep='first').reset_index(drop=True)

    if universe_type == "top100":
        return df.iloc[:100].copy().reset_index(drop=True)
    elif universe_type == "nifty500":
        return df.iloc[:500].copy().reset_index(drop=True)
    else:
        return df.iloc[:1000].copy().reset_index(drop=True)

# ============ UNIVERSE BUILDER (TOP-1500) ============
# Design:
#   base  = embedded top-1000 catalog (already turnover-ranked, untouched)
#   pool  = NSE ka live EQUITY_L list (fresher) ya embedded extras (fallback)
#   extras = pool me se best (UNIVERSE_SIZE - 1000) names, average daily
#            turnover (last ~10 sessions) se ranked
# NSE list block ho jaye to bhi 1500 pura hota hai (embedded extras se);
# dono na ho to base 1000 par chalta hai - aur diagnostics me saaf likhta hai.

NSE_LIST_URLS = [
    "https://nsearchives.nseindia.com/content/equities/EQUITY_L.csv",
    "https://archives.nseindia.com/content/equities/EQUITY_L.csv",
]
NSE_HEADERS = {
    "User-Agent": ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                   "(KHTML, like Gecko) Chrome/124.0 Safari/537.36"),
    "Accept": "text/csv,text/plain,*/*",
}
UNIVERSE_META = {}


def _embedded_extras():
    """gzip+base64 blob -> list of {symbol, name, industry} (candidate pool)."""
    raw = gzip.decompress(base64.b64decode(EXTRA_SYMBOLS_B64)).decode('utf-8')
    df = pd.read_csv(io.StringIO(raw))
    out = []
    for _, r in df.iterrows():
        sym = str(r.get('Symbol', '')).strip()
        if not sym:
            continue
        out.append({'symbol': sym,
                    'name': str(r.get('Company Name', sym)).strip() or sym,
                    'industry': str(r.get('Industry', 'Equities')).strip() or 'Equities'})
    return out


def _fetch_nse_symbols(timeout=25):
    """NSE official EQUITY_L.csv -> (list_of_rows, source). None agar reachable nahi.

    BMR_NSE_LIST_FILE env (local CSV path) test/ops ke liye override hai -
    set ho to wahi pehle try hota hai."""
    import csv as _csv
    local = os.environ.get("BMR_NSE_LIST_FILE")
    sources = ([local] if local else []) + NSE_LIST_URLS
    for src in sources:
        try:
            if str(src).startswith("http"):
                import requests
                resp = requests.get(src, headers=NSE_HEADERS, timeout=timeout)
                resp.raise_for_status()
                text = resp.text
            else:
                with open(src, encoding="utf-8", errors="ignore") as fh:
                    text = fh.read()
            rows = list(_csv.DictReader(io.StringIO(text)))
            out, seen = [], set()
            for row in rows:
                def _g(key):
                    return (row.get(key) or row.get(" " + key) or "").strip()
                sym, name, series = _g("SYMBOL"), _g("NAME OF COMPANY"), _g("SERIES")
                if series not in ("EQ", "BE"):
                    continue
                if not re.fullmatch(r"[A-Z0-9&\-]{1,20}", sym) or sym in seen:
                    continue
                seen.add(sym)
                out.append({'symbol': sym, 'name': name or sym, 'industry': 'Equities'})
            if len(out) >= 500:
                return out, str(src)
            print(f"[!] NSE list from {src} only had {len(out)} usable rows - skipping.")
        except Exception as exc:
            print(f"[!] NSE list fetch failed ({src}): {type(exc).__name__}: {str(exc)[:120]}")
    return None, None


def rank_candidates_by_turnover(cands, top_n, chunk_size=100, period="1mo", lookback=10):
    """Avg daily turnover (Close x Volume) se candidates rank karo.

    Returns (ranked_rows[:top_n], stats). Jis symbol ka data na mile uska turnover
    0 maana jata hai -> wo bottom par chala jata hai (guess se include nahi hota)."""
    stats = {'considered': len(cands), 'with_data': 0, 'chunks_ok': 0,
             'chunks_failed': [], 'top_n': top_n, 'ranked': 0}
    if top_n <= 0 or not cands:
        return [], stats
    turnover = {}
    by_ticker = {c['symbol'] + '.NS': c for c in cands}
    tickers = list(by_ticker.keys())
    for i in range(0, len(tickers), chunk_size):
        chunk = tickers[i:i + chunk_size]
        try:
            data = yf_download_retry(chunk, period=period, group_by='ticker', progress=False)
            stats['chunks_ok'] += 1
        except Exception as exc:
            stats['chunks_failed'].append(f"{i // chunk_size + 1}:{str(exc)[:80]}")
            print(f"[!] Turnover rank batch {i // chunk_size + 1} failed: {str(exc)[:100]}")
            continue
        for t in chunk:
            try:
                if len(chunk) == 1:
                    sub = data.copy()
                elif t in data:
                    sub = data[t].copy()
                else:
                    continue
                if isinstance(sub.columns, pd.MultiIndex):
                    sub.columns = sub.columns.get_level_values(0)
                sub = sub.dropna()
                if sub.empty or 'Close' not in sub or 'Volume' not in sub:
                    continue
                tv = (sub['Close'] * sub['Volume']).tail(lookback).mean()
                if np.isfinite(tv) and tv > 0:
                    turnover[t] = float(tv)
            except Exception:
                continue
    stats['with_data'] = len(turnover)
    ranked = sorted(cands, key=lambda c: turnover.get(c['symbol'] + '.NS', 0.0), reverse=True)
    ranked = [c for c in ranked if turnover.get(c['symbol'] + '.NS', 0.0) > 0][:top_n]
    stats['ranked'] = len(ranked)
    return ranked, stats


def build_universe(size=UNIVERSE_SIZE):
    """base (1000, ranked) + turnover-ranked extras -> DataFrame (symbol/name/industry)."""
    global UNIVERSE_META
    base_df = get_universe_df("top1000")
    base = [{'symbol': str(r['symbol']), 'name': str(r.get('name', r['symbol'])),
             'industry': str(r.get('industry', 'Equities'))} for _, r in base_df.iterrows()]
    need = max(int(size) - len(base), 0)
    meta = {'target': int(size), 'base': len(base), 'need': need, 'pool_source': None,
            'pool_size': 0, 'ranked_extras': 0, 'rank_chunks_failed': 0,
            'rank_with_data': 0, 'note': ''}
    rows = list(base)
    if need > 0:
        pool, src = _fetch_nse_symbols()
        if pool:
            meta['pool_source'] = f"nse_live ({src})"
        else:
            pool = _embedded_extras()
            meta['pool_source'] = 'embedded_extras (NSE list unreachable)'
        have = {b['symbol'] for b in base}
        pool = [c for c in pool if c['symbol'] not in have]
        meta['pool_size'] = len(pool)
        ranked, stats = rank_candidates_by_turnover(pool, need)
        meta['ranked_extras'] = len(ranked)
        meta['rank_with_data'] = stats['with_data']
        meta['rank_chunks_failed'] = len(stats['chunks_failed'])
        rows.extend(ranked)
        if len(ranked) < need:
            meta['note'] = (f"only {len(ranked)} of {need} extras had usable turnover data; "
                            f"universe is {len(rows)} not {size}")
    else:
        meta['note'] = 'base catalog already >= target size'
    df = pd.DataFrame(rows, columns=['symbol', 'name', 'industry'])
    df['Yahoo_Ticker'] = df['symbol'].astype(str) + ".NS"
    UNIVERSE_META = meta
    print(f"✅ Universe built: {len(df)} stocks (target {size}) | base {meta['base']} + "
          f"ranked extras {meta['ranked_extras']} | pool: {meta['pool_source']}")
    if meta['note']:
        print(f"[!] {meta['note']}")
    return df


