# ============ INDICATORS ============
import numpy as np

def calculate_technical_indicators(df):
    data = df.copy()
    close = data['Close']
    high = data['High']
    low = data['Low']

    # 1. Bollinger Bands (20 SMA, 2.0 StdDev) - ddof=0 for Pine Script v5 mathematical parity
    bb_mid = close.rolling(window=20).mean()
    bb_std = close.rolling(window=20).std(ddof=0)
    data['BB_Mid'] = bb_mid
    data['BB_Upper'] = bb_mid + (2.0 * bb_std)
    data['BB_Lower'] = bb_mid - (2.0 * bb_std)
    data['BB_Lower_Slope'] = (data['BB_Lower'] - data['BB_Lower'].shift(3)) / (data['BB_Lower'].shift(3) + 1e-9)

    # 2. RSI (14-period Wilder smoothing)
    delta = close.diff()
    gain = delta.clip(lower=0)
    loss = -delta.clip(upper=0)
    avg_gain = gain.ewm(alpha=1/14, min_periods=14, adjust=False).mean()
    avg_loss = loss.ewm(alpha=1/14, min_periods=14, adjust=False).mean()
    rs = avg_gain / (avg_loss + 1e-9)
    data['RSI'] = 100 - (100 / (1 + rs))

    # 3. MACD (12, 26, 9 EMA)
    ema12 = close.ewm(span=12, adjust=False).mean()
    ema26 = close.ewm(span=26, adjust=False).mean()
    macd_line = ema12 - ema26
    signal_line = macd_line.ewm(span=9, adjust=False).mean()
    data['MACD_Line'] = macd_line
    data['MACD_Signal'] = signal_line
    data['MACD_Hist'] = macd_line - signal_line

    # 4. Exponential Moving Averages
    data['EMA_50'] = close.ewm(span=50, adjust=False).mean()
    data['EMA_200'] = close.ewm(span=200, adjust=False).mean()

    # 5. Average True Range (ATR 14)
    tr1 = high - low
    tr2 = (high - close.shift()).abs()
    tr3 = (low - close.shift()).abs()
    tr = pd.concat([tr1, tr2, tr3], axis=1).max(axis=1)
    data['ATR'] = tr.rolling(window=14).mean()

    # 6. Relative Strength (30-day return)
    data['Return_30D'] = (close - close.shift(30)) / (close.shift(30) + 1e-9)
    data['Vol_SMA20'] = data['Volume'].rolling(window=20).mean()

    return data

def calculate_benchmark_regime(nifty_df):
    c = nifty_df['Close']
    ema50 = c.ewm(span=50, adjust=False).mean().iloc[-1]
    ema200 = c.ewm(span=200, adjust=False).mean().iloc[-1]
    cmp = c.iloc[-1]
    ret30 = (c.iloc[-1] - c.iloc[-31]) / c.iloc[-31] if len(c) > 31 else 0.0
    return {
        'cmp': float(cmp),
        'ema50': float(ema50),
        'ema200': float(ema200),
        'is_bull_market': bool(cmp > ema200 and ema50 > ema200),
        'nifty_30d_return': float(ret30)
    }

print("✅ Indicators Engine compiled with ddof=0 standard deviation parity!")


# ============ SCREENER ENGINE ============

def yf_download_retry(*args, **kwargs):
    """Retry wrapper for Yahoo Finance downloads (network hiccups). Same data, more reliable."""
    last_err = None
    for attempt in range(3):
        try:
            return yf.download(*args, **kwargs)
        except Exception as e:
            last_err = e
            print(f"[!] Download attempt {attempt+1}/3 failed: {e}. Retrying in 10s...")
            time.sleep(10)
    raise last_err

import yfinance as yf
import math


def simulate_exits(o, h, l, c, entry_idx, last_idx, entry, sl, t1, t2, plan='PARTIAL'):
    """Forward-simulate exits. FULL_T1 = all at T1. FULL_RIDE = trail at T1, all at T2. PARTIAL = 50/50. Returns (legs, t1_touched)."""
    legs = []
    rem = 1.0
    cur_sl = sl
    t1_done = False
    t1_touched = False
    end_cap = min(last_idx, entry_idx + MAX_HOLDING_DAYS - 1)
    for j in range(entry_idx, end_cap + 1):
        oj, hj, lj = float(o[j]), float(h[j]), float(l[j])
        if oj <= cur_sl:
            legs.append((j, oj, rem, 'SL-GAP')); rem = 0.0; break
        if lj <= cur_sl:
            legs.append((j, cur_sl, rem, 'SL')); rem = 0.0; break
        if (not t1_done) and hj >= t1:
            t1_touched = True
            if plan == 'FULL_T1':
                legs.append((j, t1, rem, 'T1-FULL')); rem = 0.0; break
            if plan == 'FULL_RIDE':
                if hj >= t2:
                    legs.append((j, t2, rem, 'T2')); rem = 0.0; break
                cur_sl = round(entry * 1.005, 2); t1_done = True
                continue
            legs.append((j, t1, 0.5, 'T1')); rem = 0.5
            if hj >= t2:
                legs.append((j, t2, rem, 'T2')); rem = 0.0; break
            cur_sl = round(entry * 1.005, 2); t1_done = True
            continue
        if hj >= t2:
            legs.append((j, t2, rem, 'T2')); rem = 0.0; break
    if rem > 0:
        if end_cap < last_idx:
            legs.append((end_cap, float(c[end_cap]), rem, 'TIME'))
        else:
            legs.append((last_idx, None, rem, 'OPEN'))
    return legs, t1_touched


def tracker_status(legs, entry, cmp_now, entry_idx, dates, plan='PARTIAL', t1_touched=False):
    closed = [x for x in legs if x[3] != 'OPEN']
    open_frac = sum(x[2] for x in legs if x[3] == 'OPEN')
    realised = sum(((x[1] - entry) / entry) * x[2] * 100.0 for x in closed)
    reasons = [x[3] for x in closed]
    exit_px = round(sum(x[1] * x[2] for x in closed), 2) if closed else None
    is_open = open_frac > 0
    live = realised + (open_frac * (cmp_now - entry) / entry * 100.0 if is_open else 0.0)
    today = dates[-1].date()
    entry_date = dates[entry_idx].date()
    if is_open:
        exit_date, exit_reason, fresh = '', 'OPEN', False
        days_held = (today - entry_date).days
        if plan == 'FULL_RIDE' and t1_touched:
            status, action = "OPEN (Trailed)", "Kuch mat becho - SL cost par hai, T2 tak RIDE karo"
        elif plan == 'FULL_RIDE':
            status, action = "OPEN", "Hold karo - bechna kuch nahi, T1 trail / T2 ka wait karo"
        elif live <= -1.0:
            status, action = "OPEN", "Hold karo - T1 par POORA exit karna hai, SL paas hai nazar rakho"
        else:
            status, action = "OPEN", "Hold karo - T1 par POORA exit karna hai"
    else:
        eb = closed[-1][0]
        exit_date = dates[eb].strftime('%d-%b-%Y')
        exit_reason = '+'.join(reasons)
        fresh = (today - dates[eb].date()).days <= EXIT_ALERT_DAYS
        days_held = (dates[eb].date() - entry_date).days
        if 'T2' in reasons:
            status, action = "T2 DONE", "EXIT karo - Target 2 hit! Poora profit book karo"
        elif 'T1-FULL' in reasons:
            status, action = "T1 FULL EXIT", "EXIT - T1 par poora book. Plan ke hisaab se closed"
        elif reasons == ['TIME'] or reasons == ['T1', 'TIME']:
            status, action = "TIME UP", "25 sessions pure - CMP par exit karo"
        elif 'T1' in reasons:
            status, action = "T1+SL", "T1 profit bank, runner SL par nikla - closed"
        else:
            status, action = "SL HIT", "EXIT karo - Stop Loss hit. Discipline se niklo"
    eff_sl = round(entry * 1.005, 2) if (plan == 'FULL_RIDE' and t1_touched and is_open) else None
    return {'live_pnl_pct': round(live, 2), 'status': status, 'action': action,
            'is_open': is_open, 'fresh_exit': fresh, 'exit_date': exit_date,
            'exit_reason': exit_reason, 'days_held': days_held, 'exit_price': exit_px,
            'eff_sl': eff_sl, 't1_touched': t1_touched}


# ============ PHASE 2: SHADOW TESTING (observation only) ============
# Ye block kabhi bhi actionable/email list ko nahi chhoota. Sirf ye batata hai ki
# agar filters loosen karein to kitne EXTRA signals aate, aur unka forward result
# (T1/SL/TIME) kya hota. Phase 3 ka promotion decision isi data se lena hai.
# V0 = aaj ka behaviour (baseline, comparison ke liye).
SHADOW_VARIANTS = {
    'V0_current':      dict(label='V0 baseline (aaj ka code)',        bb_slope_thr=0.012, ema50_guard=True,  macd_gate=True),
    'V1_bb3':          dict(label='V1 bb slope -1.2% -> -3.0%',       bb_slope_thr=0.030, ema50_guard=True,  macd_gate=True),
    'V2_bb3_noslope':  dict(label='V2 bb -3.0% + EMA50 guard OFF',    bb_slope_thr=0.030, ema50_guard=False, macd_gate=True),
    'V3_nomacd':       dict(label='V3 MACD turn gate OFF',            bb_slope_thr=0.012, ema50_guard=True,  macd_gate=False),
}


def _gate_stack(vals, idx, variant, nifty_ret30):
    """Trigger check with (optional) loosened thresholds. Pure function.

    Same rules as the live screener, only the variant knobs differ, so the
    comparison between shadow variants and V0 is apples-to-apples."""
    if idx < 100:
        return False
    c, o, h, l = vals['c'], vals['o'], vals['h'], vals['l']
    lb, bls, rsi, hist = vals['lb'], vals['bls'], vals['rsi'], vals['hist']
    atr, e50, e200, ret30 = vals['atr'], vals['e50'], vals['e200'], vals['ret30']
    if np.isnan(atr[idx]) or atr[idx] <= 0 or np.isnan(e200[idx]):
        return False
    if not (c[idx] > e200[idx] and e50[idx] > e200[idx]):
        return False
    if variant['ema50_guard'] and e50[idx] < e50[idx - 5] * 0.998:
        return False
    if not any(l[idx - k] <= lb[idx - k] * 1.005 for k in range(2)):
        return False
    if not (np.isnan(bls[idx]) or bls[idx] >= -variant['bb_slope_thr']):
        return False
    if not any(rsi[idx - k] <= 40 for k in range(3)):
        return False
    if not (rsi[idx] > rsi[idx - 1] and rsi[idx] >= 28):
        return False
    if variant['macd_gate'] and not (hist[idx] > hist[idx - 1]):
        return False
    if not (c[idx] > lb[idx] and c[idx] > o[idx]):
        return False
    lower_wick = min(o[idx], c[idx]) - l[idx]
    candle_range = h[idx] - l[idx] + 1e-6
    if not ((lower_wick / candle_range >= 0.20) or (c[idx] >= (h[idx] + l[idx]) * 0.50) or (c[idx] > c[idx - 1])):
        return False
    if not np.isnan(ret30[idx]) and ret30[idx] < nifty_ret30 - 0.025:
        return False
    sl = min(l[idx - 2], l[idx - 1], l[idx]) - (1.3 * atr[idx])
    risk = (c[idx] - sl) / c[idx]
    if not (0.012 <= risk <= 0.080):
        return False
    return True


def _shadow_signal_levels(vals, idx, nifty_ret30):
    """Same maths as the live signal, used for the shadow sheet's price columns."""
    c, o, h, l = vals['c'], vals['o'], vals['h'], vals['l']
    atr, ub, rsi, bls, e50 = vals['atr'], vals['ub'], vals['rsi'], vals['bls'], vals['e50']
    entry = float(c[idx])
    sl = round(min(l[idx - 2], l[idx - 1], l[idx]) - (1.3 * atr[idx]), 2)
    t1 = round(entry * (1.0 + TARGET_1_GAIN_PCT), 2)
    t2 = round(max(float(ub[idx]), entry * T2_MULT), 2)
    return dict(entry=entry, sl=sl, t1=t1, t2=t2, rsi=round(float(rsi[idx]), 1),
                bb_slope=round(float(bls[idx]) * 100.0, 2) if not np.isnan(bls[idx]) else None,
                ema50_ok=bool(e50[idx] >= e50[idx - 5] * 0.998))


def _shadow_retro(vals, last_idx, nifty_ret30, variant, plan='FULL_T1'):
    """Last TRACK_DAYS sessions ka forward-test (T1/SL/TIME/OPEN).

    Entry = signal ke agle din ka open, exit = existing simulate_exits engine.
    Sirf statistics ke liye - koi trade ya email nahi."""
    out = []
    c, o, h, l = vals['c'], vals['o'], vals['h'], vals['l']
    first = max(101, last_idx - TRACK_DAYS)
    for idx in range(first, last_idx):
        _mom = nifty_ret30(vals['dates'][idx].date()) if callable(nifty_ret30) else nifty_ret30
        if not _gate_stack(vals, idx, variant, _mom):
            continue
        e_idx = idx + 1
        entry = float(o[e_idx])
        sl = round(min(l[idx - 2], l[idx - 1], l[idx]) - (1.3 * vals['atr'][idx]), 2)
        t1 = round(entry * (1.0 + TARGET_1_GAIN_PCT), 2)
        t2 = round(max(float(vals['ub'][idx]), entry * T2_MULT), 2)
        legs, touched = simulate_exits(o, h, l, c, e_idx, last_idx, entry, sl, t1, t2, plan=plan)
        info = tracker_status(legs, entry, float(c[last_idx]), e_idx, vals['dates'], plan=plan, t1_touched=touched)
        out.append(info['status'])
    return out


def _shadow_stats(statuses):
    """Status list -> win/sl/time/open breakdown."""
    n = len(statuses)
    win = sum(1 for s in statuses if ('T1' in s or 'T2' in s))
    sl = sum(1 for s in statuses if 'SL' in s)
    t_open = sum(1 for s in statuses if s.startswith('OPEN'))
    time_up = n - win - sl - t_open
    return {'signals': n, 'wins': win, 'sl': sl, 'time': time_up, 'open': t_open,
            'win_rate': round(win / n * 100.0, 1) if n else 0.0,
            'sl_rate': round(sl / n * 100.0, 1) if n else 0.0}


def shadow_promotion_review(shadow_stats, regime_info, max_new_signals_per_day=5):
    """PHASE 3 gate - kya koi loosened variant promote karne layak hai?

    Promote sirf tab jab teenon criteria pass hon:
      1. 25-session forward-test me win-rate baseline (V0) se kam na ho
      2. signal volume cap ke andar ho (max_new_signals_per_day)
      3. NIFTY regime BULL ho (correction me loosened filters band rahenge)
    Ye function sirf VERDICT deta hai - khud kuch promote nahi karta."""
    base = shadow_stats.get('V0_current', {})
    base_wr = base.get('win_rate', 0.0)
    reviews = []
    for key, st in shadow_stats.items():
        if key == 'V0_current':
            continue
        per_day = st.get('signals', 0) / float(TRACK_DAYS) if TRACK_DAYS else 0.0
        reasons = []
        if st.get('win_rate', 0.0) < base_wr:
            reasons.append(f"win-rate {st.get('win_rate', 0):.0f}% < baseline {base_wr:.0f}%")
        if per_day > max_new_signals_per_day:
            reasons.append(f"{per_day:.1f} signals/day > cap {max_new_signals_per_day}")
        if not regime_info.get('is_bull_market', False):
            reasons.append("regime CORRECTION (only BULL me promote)")
        reviews.append({
            'variant': key,
            'label': SHADOW_VARIANTS[key]['label'],
            'verdict': 'READY' if not reasons else 'NOT-READY',
            'reasons': '; '.join(reasons) if reasons else 'all criteria met',
            'signals': st.get('signals', 0),
            'win_rate': st.get('win_rate', 0.0),
            'signals_per_day': round(per_day, 2),
        })
    return reviews


def run_screener(universe_df, capital=500000, risk_pct=1.0):
    print(f"[*] Fetching benchmark data ({BENCHMARK_TICKER})...")
    nifty = yf_download_retry(BENCHMARK_TICKER, period="1y", progress=False)
    if isinstance(nifty.columns, pd.MultiIndex):
        nifty.columns = nifty.columns.get_level_values(0)
    regime = calculate_benchmark_regime(nifty)

    regime_desc = "BULL MARKET (Safe to Swing Trade)" if regime['is_bull_market'] else "CORRECTION (Caution Recommended)"
    _nc = nifty['Close']
    nifty_mom_map = {}
    for _k in range(30, len(_nc)):
        _dd = nifty.index[_k]
        _dd = _dd.date() if hasattr(_dd, "date") else _dd
        nifty_mom_map[_dd] = float((_nc.iloc[_k] - _nc.iloc[_k-30]) / _nc.iloc[_k-30])
    def _nifty_mom_on(_d):
        if _d in nifty_mom_map:
            return nifty_mom_map[_d]
        _past = [x for x in nifty_mom_map.keys() if x <= _d]
        return nifty_mom_map[max(_past)] if _past else regime['nifty_30d_return']
    print(f"[+] NIFTY 50 CMP: ₹{regime['cmp']:,.2f} | 200 EMA: ₹{regime['ema200']:,.2f}")
    print(f"[+] Market Regime: {regime_desc}\n")

    if ENFORCE_NIFTY_REGIME and not regime['is_bull_market']:
        print("[!] Nifty 50 is in Correction/Bear regime and ENFORCE_NIFTY_REGIME is True. Screener will prioritize cash preservation.")

    tickers = universe_df['Yahoo_Ticker'].tolist()
    total_tickers = len(tickers)
    chunk_size = 100
    chunks = [tickers[i:i + chunk_size] for i in range(0, total_tickers, chunk_size)]

    meta_dict = {
        row['Yahoo_Ticker']: {
            'symbol': row['symbol'],
            'name': row.get('name', row['symbol']),
            'industry': row.get('industry', 'Equities')
        }
        for _, row in universe_df.iterrows()
    }

    actionable_signals = []
    watchlist_candidates = []
    recent_signals = []

    # ---- PHASE 1 DIAGNOSTICS (observation only, koi selection change nahi) ----
    # Har run ye batata hai: kitna data aaya, kahan fail hua, aur "0 signal" ka
    # karan kaunsa gate tha. Pehle ye sab chupchaap hota tha.
    _UM = dict(UNIVERSE_META or {})
    diag = {
        'universe_target': _UM.get('target', len(universe_df)),
        'universe_pool_source': _UM.get('pool_source'),
        'universe_pool_size': _UM.get('pool_size', 0),
        'universe_ranked_extras': _UM.get('ranked_extras', 0),
        'universe_rank_with_data': _UM.get('rank_with_data', 0),
        'universe_rank_chunks_failed': _UM.get('rank_chunks_failed', 0),
        'universe_note': _UM.get('note', ''),
        'universe_requested': int(len(universe_df)) + len(UNIVERSE_DUPLICATES),
        'universe_unique': int(len(universe_df)),
        'duplicates_skipped': list(UNIVERSE_DUPLICATES),
        'batches_total': len(chunks),
        'batches_failed': [],
        'tickers_requested': len(tickers),
        'tickers_scanned': 0,
        'tickers_missing_from_download': 0,
        'tickers_insufficient_history': 0,
        'tickers_nan_indicators': 0,
        'tickers_calc_error': 0,
        'ticker_error_samples': [],
        'latest_bar_nan_close': 0,
        'stale_tickers': 0,
        'stale_ticker_samples': [],
        'data_as_of': None,
        'market_date': None,
        'reject_first_gate': {},
        'shadow_today': {k: 0 for k in SHADOW_VARIANTS},
        'shadow_retro': {k: {'signals': 0, 'wins': 0, 'sl': 0, 'time': 0, 'open': 0,
                             'win_rate': 0.0, 'sl_rate': 0.0} for k in SHADOW_VARIANTS},
        'shadow_today_signals': [],
        'generated_at_ist': None,
    }
    _GATE_ORDER = ['ema50_slope', 'rs_vs_nifty', 'bb_lower_pierce', 'bb_slope_ok',
                   'rsi_oversold', 'rsi_hook', 'macd_turn', 'candle_ok', 'wick_ok']

    def _gate_fail(name):
        diag['reject_first_gate'][name] = diag['reject_first_gate'].get(name, 0) + 1

    try:
        _bench_last = nifty.index[-1]
        diag['market_date'] = (_bench_last.date() if hasattr(_bench_last, 'date') else _bench_last)
    except Exception:
        diag['market_date'] = None

    for c_i, chunk in enumerate(chunks, 1):
        print(f"[*] Scanning Batch {c_i}/{len(chunks)} ({len(chunk)} stocks)...")
        try:
            data = yf_download_retry(chunk, period="1y", group_by='ticker', progress=False)
        except Exception as e:
            print(f"Error in batch {c_i}: {e}")
            # PHASE 1 fix: pehle ye batch chupchaap gayab ho jata tha (100 stocks
            # silently missing, run phir bhi green). Ab report me dikhta hai.
            diag['batches_failed'].append({'batch': c_i, 'stocks': len(chunk), 'error': str(e)[:200]})
            continue

        for ticker in chunk:
            try:
                df = None
                if len(chunk) == 1:
                    df = data.copy()
                    if isinstance(df.columns, pd.MultiIndex):
                        df.columns = df.columns.get_level_values(0)
                else:
                    if ticker in data:
                        df = data[ticker].copy()

                if df is None or df.empty:
                    diag['tickers_missing_from_download'] += 1
                    continue

                # PHASE 1 fix (fresh-bar): Yahoo market close ke baad naye bar me
                # Close=NaN deta hai. Pehle wo bar dropna() se chupchaap hat jata
                # tha -> screener kal ki candle par chal raha hota tha, par report
                # aaj ki date dikhati thi. Ab detect + report hota hai (selection
                # waisi hi rahti hai, bas "data as of" sach bolta hai).
                if len(df) and pd.isna(df['Close'].iloc[-1]):
                    diag['latest_bar_nan_close'] += 1

                if len(df.dropna()) < 120:
                    diag['tickers_insufficient_history'] += 1
                    continue
                df = df.dropna()
                if isinstance(df.columns, pd.MultiIndex):
                    df.columns = df.columns.get_level_values(0)

                # Data freshness: is ticker ka last candle market date se peeche hai?
                try:
                    _td = df.index[-1]
                    _td = _td.date() if hasattr(_td, 'date') else _td
                    if diag['data_as_of'] is None or _td > diag['data_as_of']:
                        diag['data_as_of'] = _td
                    if diag['market_date'] is not None and _td < diag['market_date']:
                        diag['stale_tickers'] += 1
                        if len(diag['stale_ticker_samples']) < 5:
                            diag['stale_ticker_samples'].append(f"{ticker}@{_td}")
                except Exception:
                    pass

                diag['tickers_scanned'] += 1

                df = calculate_technical_indicators(df)
                meta = meta_dict.get(ticker, {'symbol': ticker.replace('.NS', ''), 'name': ticker, 'industry': 'Equities'})

                i = len(df) - 1
                c = df['Close'].values
                h = df['High'].values
                l = df['Low'].values
                o = df['Open'].values
                vol = df['Volume'].values
                vol_sma = df['Vol_SMA20'].values
                ema50 = df['EMA_50'].values
                ema200 = df['EMA_200'].values
                bb_mid = df['BB_Mid'].values
                bb_up = df['BB_Upper'].values
                bb_low = df['BB_Lower'].values
                bb_low_slope = df['BB_Lower_Slope'].values
                rsi = df['RSI'].values
                hist = df['MACD_Hist'].values
                atr = df['ATR'].values
                ret30 = df['Return_30D'].values
                dates = df.index

                if np.isnan(atr[i]) or atr[i] <= 0 or np.isnan(ema200[i]):
                    diag['tickers_nan_indicators'] += 1
                    continue

                cmp = c[i]
                is_uptrend = (cmp > ema200[i]) and (ema50[i] > ema200[i])
                _pend = None

                # Check regime enforcement
                if ENFORCE_NIFTY_REGIME and not regime['is_bull_market']:
                    pass # Enforce cash mode
                else:
                    # --- 1. ACTIONABLE TRADE EVALUATION (7 CONFLUENCE RULES) ---
                    if is_uptrend:
                        # Rule 2: 50 EMA Slope Guard
                        slope_ok = not (ema50[i] < ema50[i-5] * 0.998)
                        # Rule 3: Relative Strength vs Nifty 50
                        rs_ok = True if np.isnan(ret30[i]) else (ret30[i] >= regime['nifty_30d_return'] - 0.025)
                        # Rule 4: Lower Band Touch
                        pierced_lower = any(l[i-k] <= bb_low[i-k] * 1.005 for k in range(2))
                        # Rule 5: Lower Band Slope Filter
                        bb_slope_ok = not (not np.isnan(bb_low_slope[i]) and bb_low_slope[i] < -0.012)
                        # Rule 6: RSI Reversal Hook
                        rsi_oversold = any(rsi[i-k] <= 40 for k in range(3))
                        rsi_hook = (rsi[i] > rsi[i-1]) and (rsi[i] >= 28)
                        # Rule 7: MACD Selling Deceleration
                        macd_turning = hist[i] > hist[i-1]
                        # Candlestick Confirmation
                        candle_ok = (cmp > bb_low[i]) and (cmp > o[i])
                        lower_wick = min(o[i], cmp) - l[i]
                        candle_range = h[i] - l[i] + 1e-6
                        wick_ok = (lower_wick / candle_range >= 0.20) or (cmp >= (h[i] + l[i]) * 0.50) or (cmp > c[i-1])

                        # PHASE 1 diagnostics: "0 signal kyun?" ka jawab.
                        # Sabse pehla gate jo block karta hai, wahi count hota hai.
                        _gate_ok = [
                            ('ema50_slope', slope_ok), ('rs_vs_nifty', rs_ok),
                            ('bb_lower_pierce', pierced_lower), ('bb_slope_ok', bb_slope_ok),
                            ('rsi_oversold', rsi_oversold), ('rsi_hook', rsi_hook),
                            ('macd_turn', macd_turning), ('candle_ok', candle_ok),
                            ('wick_ok', wick_ok),
                        ]
                        for _gn, _gok in _gate_ok:
                            if not _gok:
                                _gate_fail(_gn)
                                break

                        if slope_ok and rs_ok and pierced_lower and bb_slope_ok and rsi_oversold and rsi_hook and macd_turning and (candle_ok and wick_ok):
                            entry_price = cmp
                            recent_swing_low = min(l[i-2], l[i-1], l[i])
                            stop_loss = round(recent_swing_low - (1.3 * atr[i]), 2)
                            risk_per_share = round(entry_price - stop_loss, 2)

                            if risk_per_share > 0:
                                trade_risk_pct = (risk_per_share / entry_price) * 100.0

                                # Noise Buffer & Loose Stop Filter (1.2% <= risk <= 8.0%)
                                if not (1.2 <= trade_risk_pct <= 8.0):
                                    _gate_fail('risk_band')
                                if 1.2 <= trade_risk_pct <= 8.0:
                                    target_1 = round(entry_price * (1.0 + TARGET_1_GAIN_PCT), 2)
                                    target_2 = round(max(bb_up[i], entry_price * T2_MULT), 2)

                                    t1_gain = round(target_1 - entry_price, 2)
                                    t2_gain = round(target_2 - entry_price, 2)
                                    avg_gain = (0.5 * t1_gain) + (0.5 * t2_gain)
                                    rr_ratio = round(avg_gain / risk_per_share, 2)

                                    # FIXED: 1% per-trade risk (param) use karo, stop-distance % nahi
                                    risk_capital = capital * (risk_pct / 100.0)
                                    suggested_shares = max(int(math.floor(risk_capital / risk_per_share)), 1)
                                    suggested_shares = min(suggested_shares, max(int(capital // entry_price), 1))
                                    total_investment = round(suggested_shares * entry_price, 2)

                                    score = 0
                                    if rsi[i] < 35: score += 1
                                    if vol[i] > vol_sma[i]: score += 1
                                    if ret30[i] > regime['nifty_30d_return'] + 0.03: score += 1
                                    if rr_ratio >= 2.0: score += 1
                                    if bb_low_slope[i] > 0: score += 1

                                    rank = "A+" if score >= 4 else ("A" if score >= 2 else "A-")
                                    g_score = 0
                                    if (not np.isnan(ret30[i])) and ret30[i] > regime['nifty_30d_return'] + 0.03: g_score += 1
                                    if rsi[i] < 55: g_score += 1
                                    if hist[i] > 0: g_score += 1
                                    if vol[i] > vol_sma[i]: g_score += 1
                                    guidance = "RIDE" if g_score >= 3 else "BOOK-FAST"
                                    plan = "FULL_RIDE" if g_score >= 3 else "FULL_T1"
                                    _pend = {
                                        'rank': rank,
                                        'symbol': meta['symbol'],
                                        'name': meta['name'],
                                        'industry': meta['industry'],
                                        'entry_price': entry_price,
                                        'stop_loss': stop_loss,
                                        'risk_per_share': risk_per_share,
                                        'risk_pct': round(trade_risk_pct, 2),
                                        'target_1': target_1,
                                        't1_gain_pct': round((t1_gain / entry_price) * 100.0, 2),
                                        'target_2': target_2,
                                        't2_gain_pct': round((t2_gain / entry_price) * 100.0, 2),
                                        'rr_ratio': rr_ratio,
                                        'suggested_shares': suggested_shares,
                                        'total_investment': total_investment,
                                        'max_holding_days': MAX_HOLDING_DAYS,
                                        'rsi': round(float(rsi[i]), 1),
                                        'macd_hist': round(float(hist[i]), 2),
                                        'guidance': guidance,
                                        'g_score': g_score,
                                        'plan': plan,
                                        'tier': ('ULTRA' if g_score >= 2 else 'STANDARD')
                                    }

                # --- 2. RADAR WATCHLIST EVALUATION ---
                if is_uptrend and _pend is None:
                    dist_to_bb_low = (cmp - bb_low[i]) / cmp
                    if 0.0 <= dist_to_bb_low <= 0.035 and rsi[i] <= 45.0:
                        watchlist_candidates.append({
                            'symbol': meta['symbol'],
                            'name': meta['name'],
                            'industry': meta['industry'],
                            'cmp': cmp,
                            'bb_lower': round(bb_low[i], 2),
                            'dist_to_bb_low_pct': round(dist_to_bb_low * 100.0, 2),
                            'rsi': round(float(rsi[i]), 1),
                            'macd_hist': round(float(hist[i]), 2),
                            'macd_turning': "YES (Turning)" if hist[i] > hist[i-1] else "No (Waiting)",
                            'trigger_condition': "Consolidating at Lower BB Support; Watch for green hook"
                        })

                # --- 2b. PHASE 2 SHADOW TEST (observation only - NEVER actionable) ---
                try:
                    _vals = {'c': c, 'o': o, 'h': h, 'l': l, 'lb': bb_low, 'ub': bb_up,
                             'bls': bb_low_slope, 'rsi': rsi, 'hist': hist, 'atr': atr,
                             'e50': ema50, 'e200': ema200, 'ret30': ret30, 'dates': dates}
                    for _vkey, _v in SHADOW_VARIANTS.items():
                        if _gate_stack(_vals, i, _v, regime['nifty_30d_return']):
                            diag['shadow_today'][_vkey] += 1
                            if _vkey != 'V0_current' and _pend is None:
                                _lvl = _shadow_signal_levels(_vals, i, regime['nifty_30d_return'])
                                diag['shadow_today_signals'].append({
                                    'variant': _vkey, 'variant_label': _v['label'],
                                    'symbol': meta['symbol'], 'name': meta['name'],
                                    'cmp': round(float(_lvl['entry']), 2),
                                    'stop_loss': _lvl['sl'], 'target_1': _lvl['t1'], 'target_2': _lvl['t2'],
                                    'rsi': _lvl['rsi'], 'bb_slope_pct': _lvl['bb_slope'],
                                    'ema50_ok': _lvl['ema50_ok'],
                                })
                        _statuses = _shadow_retro(_vals, i, _nifty_mom_on, _v)
                        _st = _shadow_stats(_statuses)
                        _agg = diag['shadow_retro'][_vkey]
                        for _k in _st:
                            _agg[_k] = _agg.get(_k, 0) + _st[_k]
                    # aggregate rates (counts aggregate hue, rates dobara calc)
                    for _vkey in SHADOW_VARIANTS:
                        _a = diag['shadow_retro'][_vkey]
                        _a['win_rate'] = round(_a['wins'] / _a['signals'] * 100.0, 1) if _a['signals'] else 0.0
                        _a['sl_rate'] = round(_a['sl'] / _a['signals'] * 100.0, 1) if _a['signals'] else 0.0
                except Exception as _shadow_err:
                    if len(diag['ticker_error_samples']) < 5:
                        diag['ticker_error_samples'].append(f"shadow:{ticker}:{type(_shadow_err).__name__}:{_shadow_err}")

                # --- 3. POSITION TRACKER (signals from last TRACK_DAYS, simulated to today) ---
                _ticker_busy = -1
                for offset in range(TRACK_DAYS, 0, -1):
                    p_i = i - offset
                    if p_i < 100: continue
                    if p_i <= _ticker_busy: continue
                    if not (c[p_i] > ema200[p_i] and ema50[p_i] > ema200[p_i]): continue
                    if ema50[p_i] < ema50[p_i-5] * 0.998: continue
                    _nm0 = _nifty_mom_on(dates[p_i].date())
                    if not (True if np.isnan(ret30[p_i]) else (ret30[p_i] >= _nm0 - 0.025)): continue
                    if bb_low_slope[p_i] < -0.012: continue
                    if not any(l[p_i-k] <= bb_low[p_i-k] * 1.005 for k in range(2)): continue
                    if not (any(rsi[p_i-k] <= 40 for k in range(3)) and rsi[p_i] > rsi[p_i-1] and rsi[p_i] >= 28): continue
                    if not (hist[p_i] > hist[p_i-1]): continue
                    _lw0 = min(o[p_i], c[p_i]) - l[p_i]
                    _wick0 = (_lw0 / (h[p_i] - l[p_i] + 1e-6) >= 0.20) or (c[p_i] >= (h[p_i] + l[p_i]) * 0.50) or (c[p_i] > c[p_i-1])
                    if not ((c[p_i] > bb_low[p_i]) and (c[p_i] > o[p_i]) and _wick0): continue

                    sig_close = c[p_i]
                    p_sl = round(min(l[p_i-2], l[p_i-1], l[p_i]) - (1.3 * atr[p_i]), 2)
                    p_risk = sig_close - p_sl
                    if p_risk <= 0 or not (0.012 <= (p_risk / sig_close) <= 0.08): continue

                    e_idx = p_i + 1
                    if e_idx > i: continue
                    e_price = float(o[e_idx])
                    if e_price <= p_sl: continue
                    if (e_price - sig_close) / sig_close > 0.015: continue
                    p_t1 = round(e_price * (1.0 + TARGET_1_GAIN_PCT), 2)
                    p_t2 = round(max(float(bb_up[p_i]), e_price * T2_MULT), 2)
                    _gs = 0
                    _nm = _nifty_mom_on(dates[p_i].date())
                    if (not np.isnan(ret30[p_i])) and ret30[p_i] > _nm + 0.03: _gs += 1
                    if rsi[p_i] < 55: _gs += 1
                    if hist[p_i] > 0: _gs += 1
                    if vol[p_i] > vol_sma[p_i]: _gs += 1
                    _tplan = 'FULL_RIDE' if _gs >= 3 else 'FULL_T1'
                    legs, _touched = simulate_exits(o, h, l, c, e_idx, i, e_price, p_sl, p_t1, p_t2, plan=_tplan)
                    tinfo = tracker_status(legs, e_price, float(c[i]), e_idx, dates, plan=_tplan, t1_touched=_touched)
                    recent_signals.append({
                        'symbol': meta['symbol'],
                        'name': meta['name'],
                        'industry': meta['industry'],
                        'trigger_date': dates[p_i].strftime('%d-%b-%Y'),
                        'days_ago': offset,
                        'entry_price': e_price,
                        'stop_loss': p_sl,
                        'target_1': p_t1,
                        'target_2': p_t2,
                        'cmp': float(c[i]),
                        'live_pnl_pct': tinfo['live_pnl_pct'],
                        'status': tinfo['status'],
                        'action': tinfo['action'],
                        'is_open': tinfo['is_open'],
                        'fresh_exit': tinfo['fresh_exit'],
                        'exit_date': tinfo['exit_date'],
                        'exit_reason': tinfo['exit_reason'],
                        'exit_price': tinfo['exit_price'],
                        'eff_sl': tinfo['eff_sl'],
                        't1_touched': tinfo['t1_touched'],
                        'days_held': tinfo['days_held'],
                        'guidance': ('RIDE' if _tplan == 'FULL_RIDE' else 'BOOK-FAST'),
                        'plan': _tplan,
                        'g_score': _gs,
                        'tier': ('ULTRA' if _gs >= 2 else 'STANDARD'),
                    })
                    _ticker_busy = legs[-1][0]
                if _pend is not None and _ticker_busy < i:
                    actionable_signals.append(_pend)
            except Exception as _tick_err:
                # PHASE 1 fix: pehle yahan `continue` tha - koi bhi error chupchaap
                # ticker skip kar deta tha aur run green rehta tha.
                diag['tickers_calc_error'] += 1
                if len(diag['ticker_error_samples']) < 5:
                    diag['ticker_error_samples'].append(
                        f"{ticker}: {type(_tick_err).__name__}: {str(_tick_err)[:160]}")
                continue

    rank_order = {'A+': 3, 'A': 2, 'A-': 1}
    actionable_signals.sort(key=lambda x: (rank_order.get(x['rank'], 0), x['rr_ratio']), reverse=True)
    watchlist_candidates.sort(key=lambda x: x['dist_to_bb_low_pct'])
    recent_signals.sort(key=lambda x: x['days_ago'])

    # ---- PHASE 1/2 diagnostics ko finalize karo ----
    diag['data_as_of'] = str(diag['data_as_of']) if diag['data_as_of'] else None
    diag['market_date'] = str(diag['market_date']) if diag['market_date'] else None
    diag['generated_at_ist'] = now_ist().strftime('%d-%b-%Y %H:%M IST') if 'now_ist' in globals() else None
    diag['reject_first_gate'] = dict(sorted(diag['reject_first_gate'].items(), key=lambda kv: -kv[1]))
    diag['promotion_review'] = shadow_promotion_review(diag['shadow_retro'], regime)

    return {
        'actionable': actionable_signals,
        'watchlist': watchlist_candidates,
        'recent': recent_signals,
        'diagnostics': diag,
    }, regime

